94: /**
95:  * @brief Destructor — deletes the persistent OTA worker task.
96:  *
97:  * vTaskDeleteWithCaps() is the correct paired destructor for tasks created
98:  * with xTaskCreateWithCaps(). vTaskDelete() cannot free caps-allocated stacks
99:  * and would leak 16 KB of DRAM. Safe if begin() was never called (_taskHandle
100:  * will be nullptr and the guard skips the delete).
101:  */
102: OTAUpdateManager::~OTAUpdateManager() {
103:     if (_taskHandle != nullptr) {
104:         TaskHandle_t handle = _taskHandle;
105:         clearTaskHandle_();                 // null the member first (no dangling access)
106:         vTaskDeleteWithCaps(handle);        // free the caps-allocated DRAM stack
107:     }
108: }
