141:  * @param section Read-only reference to the JSON object containing config keys.
142:  */
143: void OTAUpdateManager::applyConfig(const JsonObject& section) {
144:     const char* ch = section["channel"] | "stable";
145:     strlcpy(_channel, ch, sizeof(_channel));
146:     _autoCheck      = section["autoCheck"]      | true;
147:     _updatesEnabled = section["updatesEnabled"] | true;
148:     const char* lcc = section["lastCheckedChannel"] | "";
149:     strlcpy(_lastCheckedChannel, lcc, sizeof(_lastCheckedChannel));
150:     _checkHour = section["checkHour"] | (uint8_t)3;
151:     if (_checkHour > 23) _checkHour = 3; // Clamp invalid values
152:     const char* lmu = section["learnedManifestUrl"] | "";
153:     strlcpy(_learnedManifestUrl, lmu, sizeof(_learnedManifestUrl));
154:     ESP_LOGI(TAG, "Config applied — channel='%s' autoCheck=%d updatesEnabled=%d checkHour=%u lastCheckedChannel='%s' learnedManifestUrl='%s'",
155:              _channel, (int)_autoCheck, (int)_updatesEnabled, (unsigned)_checkHour, _lastCheckedChannel, _learnedManifestUrl);
