224: /**
225:  * @brief Initialize the OTA manager with dependencies from the Application.
226:  *
227:  * Extracts narrow references to the 3 services this module actually uses,
228:  * then discards the Application reference (Transient Service Locator, ADR-39).
229:  */
230: void OTAUpdateManager::begin(Application& app) {
231:     _config        = &app.getConfig();
232:     _configManager = &app.getConfigManager();
233:     _eventBus      = &app.getEventBus();
234: 
235:     // --- Create the persistent OTA worker task (once per device lifetime) ---
236:     // Stack MUST be in DRAM (MALLOC_CAP_INTERNAL) because the OTA pipeline
237:     // performs SPI flash writes. PSRAM-stack tasks are unsafe for flash I/O
238:     // (the SPI cache is disabled during flash ops, making PSRAM inaccessible).
239:     // Pre-flight DRAM check: task creation here — where memory is most abundant
240:     // — is far safer than dynamic allocation on every performUpdate() call.
241:     uint32_t freeDram = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
242:     ESP_LOGI(TAG, "Creating OTA worker task (stack=%" PRIu32 " B, free DRAM=%" PRIu32 " B)",
243:              OTA_TASK_STACK_BYTES, freeDram);
244: 
245:     BaseType_t result = xTaskCreateWithCaps(
246:         otaTaskLoop,
247:         "ota_worker",
248:         OTA_TASK_STACK_BYTES,
249:         this,
250:         5,
251:         &_taskHandle,
252:         MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT
253:     );
254: 
255:     if (result != pdPASS) {
256:         ESP_LOGE(TAG,
257:             "Failed to create OTA worker task — "
258:             "free DRAM: %" PRIu32 " B, stack required: %" PRIu32 " B. "
259:             "OTA checks will not be available until reboot.",
260:             freeDram, OTA_TASK_STACK_BYTES);
261:         _taskHandle = nullptr;
262:     } else {
263:         ESP_LOGI(TAG, "OTA worker task created (persistent, DRAM stack)");
264:     }
265: }
