267: /**
268:  * @brief Periodic tick — handles boot auto-check and daily scheduled check.
269:  *
270:  * Called by the Application main loop. Must complete in ≤10ms; all heavy
271:  * work is deferred to the FreeRTOS task launched by performUpdate().
272:  *
273:  * Boot check: fires once on the first tick after Wi-Fi is confirmed
274:  *   connected (WiFi.status() == WL_CONNECTED) if autoCheck is enabled.
275:  *
276:  * Daily check: fires once per calendar day when the wall-clock hour
277:  *   matches _checkHour and autoCheck is enabled. Requires NTP sync
278:  *   (time() > 1 000 000) and an active Wi-Fi connection.
279:  */
280: void OTAUpdateManager::tick(uint32_t currentMillis) {
281:     if (!_autoCheck || _state != OTAState::Idle) return;
282: 
283:     // Gate: do not attempt any network operation until Wi-Fi is confirmed up.
284:     // This prevents the boot check from racing the TLS/DNS stack during the
285:     // first few seconds after association, and prevents the daily check from
286:     // firing during a temporary network outage.
287:     if (WiFi.status() != WL_CONNECTED) return;
288: 
289:     // --- Boot check: fire once, after Wi-Fi is confirmed connected ---
290:     if (!_hasBootChecked) {
291:         _hasBootChecked = true;
292:         _silentCheck = true;  // Boot checks never show error modals
293:         ESP_LOGI(TAG, "Auto-check: boot trigger (Wi-Fi confirmed connected)");
294:         performUpdate();
295:         return;
296:     }
297: 
298:     // --- Daily scheduled check at _checkHour ---
299:     time_t now = time(nullptr);
300:     if (now < 1000000UL) return; // NTP not yet synced
301: 
302:     struct tm t;
303:     localtime_r(&now, &t);
304:     uint32_t today = static_cast<uint32_t>(now / 86400);
305: 
306:     if (static_cast<uint8_t>(t.tm_hour) == _checkHour && today > _lastCheckDay) {
307:         _lastCheckDay = today;
308:         _silentCheck = true;  // Scheduled checks never show error modals
309:         ESP_LOGI(TAG, "Auto-check: daily trigger at hour %u", (unsigned)_checkHour);
310:         performUpdate();
311:     }
312: }
