315:  * @brief Check for a newer firmware version.
316:  *
317:  * Guards: must be in Idle state and have a configured otaManifestUrl.
318:  * On native: always returns false.
319:  *
320:  * The full manifest-first check is performed by performUpdateTask().
321:  * This standalone method is retained for the MCP ota_check_now tool
322:  * and returns false until a lightweight manifest-only check is wired.
323:  */
324: bool OTAUpdateManager::checkForUpdate() {
325:     // Guard: must be initialized
326:     if (_config == nullptr) {
327:         ESP_LOGE(TAG, "checkForUpdate() called before begin() — returning false");
328:         return false;
329:     }
330: 
331:     // Guard: must be in Idle state
332:     if (_state != OTAState::Idle) {
333:         ESP_LOGW(TAG, "checkForUpdate() called while state != Idle — returning false");
334:         return false;
335:     }
336: 
337:     // Guard: must have at least one manifest URL source (compiled-in or learned)
338:     if (_config->otaManifestUrl == nullptr && _learnedManifestUrl[0] == '\0') {
339:         ESP_LOGW(TAG, "checkForUpdate() — no manifest URL configured (compiled-in or learned) — returning false");
340:         return false;
341:     }
342: 
343:     _state = OTAState::Checking;
344:     _lastCheckTimer.reset(millis());
345:     ESP_LOGI(TAG, "Checking for updates — local: %s, channel: '%s'", BUILD_VERSION, _channel);
346: 
347:     // Manifest-first check is performed by performUpdateTask(). This method
348:     // returns false until a lightweight manifest-only version check is wired.
349:     ESP_LOGW(TAG, "checkForUpdate() — use performUpdate() for manifest-first check");
