354: /**
355:  * @brief Start the full OTA download + verify + flash pipeline.
356:  *
357:  * Launches a FreeRTOS task and returns immediately. The task runs
358:  * performUpdateTask() which handles the complete pipeline. On native
359:  * builds, sets state to Error (no FreeRTOS available).
360:  */
361: void OTAUpdateManager::performUpdate() {
362:     // Guard: must be initialized (begin() creates the worker task)
363:     if (_config == nullptr) {
364:         ESP_LOGE(TAG, "performUpdate() called before begin()");
365:         _state = OTAState::Error;
366:         _lastOtaError = "OTA manager not initialized";
367:         return;
368:     }
369: 
370:     // Guard: must be in Idle state
371:     if (_state != OTAState::Idle) {
372:         ESP_LOGW(TAG, "performUpdate() called while state != Idle — ignoring");
373:         return;
374:     }
375: 
376:     // Guard: worker task must be running (begin() may have failed to create it)
377:     if (_taskHandle == nullptr) {
378:         ESP_LOGE(TAG, "OTA worker task unavailable — begin() not called or task creation failed");
379:         _state = OTAState::Error;
380:         _lastOtaError = "OTA worker task unavailable";
381:         publishProgress(0.0f, "OTA worker task unavailable", true, false);
382:         return;
383:     }
384: 
385:     // Transition state first (before notify, so the task sees Checking on wake)
386:     _state = OTAState::Checking;
387:     ESP_LOGI(TAG, "Notifying OTA worker task to begin pipeline");
388: 
389:     // Wake the persistent worker task — zero allocation, returns immediately.
390:     // The task was created with xTaskCreateWithCaps(MALLOC_CAP_INTERNAL) in
391:     // begin(). Its DRAM stack is reused for every OTA check; no per-cycle
392:     // heap allocation occurs here.
393:     xTaskNotifyGive(_taskHandle);
394: }
