396: /**
397:  * @brief Persistent FreeRTOS task loop — blocks on TaskNotify between OTA checks.
398:  *
399:  * Runs for the lifetime of the device. Each performUpdate() call wakes this
400:  * task via xTaskNotifyGive(). After performUpdateTask() completes (or the
401:  * pipeline reaches reboot), the loop returns to blocking sleep, ready for
402:  * the next check. No memory is allocated or freed per cycle.
403:  *
404:  * Deletion: only from ~OTAUpdateManager() via vTaskDeleteWithCaps(_taskHandle).
405:  * vTaskDelete() must NOT be called here — it cannot free caps-allocated stacks.
406:  */
407: void OTAUpdateManager::otaTaskLoop(void* param) {
408:     auto* self = static_cast<OTAUpdateManager*>(param);
409:     for (;;) {
410:         // Block until performUpdate() sends a notification
411:         ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
412:         self->performUpdateTask();
413:     }
414: }
