416: /**
417:  * @brief Null out _taskHandle.
418:  *
419:  * Called from the destructor immediately before vTaskDeleteWithCaps() to
420:  * ensure the stale handle cannot be read after deletion.
421:  */
422: void OTAUpdateManager::clearTaskHandle_() {
423:     _taskHandle = nullptr;
424: }
