426: /**
427:  * @brief Execute the full OTA pipeline inside the FreeRTOS task.
428:  *
429:  * Manifest-first flow (WO3 rewire):
430:  *   1. Fetch + verify manifest via fetchAndVerifyManifest_()
431:  *   2. Channel lookup via findChannel()
432:  *   3. SemVer version comparison
433:  *   4. Board asset lookup via findAssetForBoard()
434:  *   5. Snapshot config manifest (Active → Previous)
435:  *   6. Initialize the verifier (if public key configured)
436:  *   7. Create WiFiClientSecure on the heap
437:  *   8. Create OTADownloadEngine and configure
438:  *   9. Fetch signature file via asset URL
439:  *  10. Download and flash firmware via asset URL
440:  *  11. Finalize and reboot
441:  */
442: void OTAUpdateManager::performUpdateTask() {
443:     ESP_LOGI(TAG, "OTA task started (manifest-first flow)");
444:     AUDIT("ota", "pipeline_start");
445: 
446:     // NOTE: Do NOT register this task with TWDT here. The OTA pipeline makes
447:     // multiple blocking HTTPS calls (manifest, signature, firmware) involving
448:     // TLS handshakes that take 5-15+ seconds each. TWDT is registered only
449:     // during the firmware download phase (Step 10), where the progress
450:     // callback feeds it every ~4KB.
451: 
452:     const FrameworkConfig& cfg = *_config;
453: 
454:     // --- Guard: firmware updates must be enabled (persisted OTA config) ---
455:     if (!_updatesEnabled) {
456:         ESP_LOGW(TAG, "Firmware updates are disabled in config");
457:         publishProgress(0.0f, "Firmware updates disabled", true, false);
458:         _state = OTAState::Error;
459:         _lastOtaError = "Firmware updates disabled";
460:         return;
461:     }
462: 
463:     // --- Guard: at least one manifest URL must be available ---
464:     // Check both compiled-in URL and learned URL. fetchAndVerifyManifest_
465:     // handles the fallback logic; we only reject if neither source exists.
466:     if (cfg.otaManifestUrl == nullptr && _learnedManifestUrl[0] == '\0') {
467:         if (_silentCheck) {
468:             // Boot/scheduled checks: suppress error, return to idle
469:             _state = OTAState::Idle;
470:             _silentCheck = false;
471:             return;
472:         }
473:         ESP_LOGE(TAG, "No manifest URL configured (compiled-in or learned)");
474:         publishProgress(0.0f, "No manifest URL configured", true, false);
475:         _state = OTAState::Error;
476:         _lastOtaError = "No manifest URL configured";
477:         return;
478:     }
479: 
480:     // --- Step 1: Fetch, verify, and parse the manifest ---
481:     _lastCheckTimer.reset(millis());
482:     ESP_LOGI(TAG, "Fetching manifest — channel: '%s', local: %s", _channel, BUILD_VERSION);
483: 
484:     OTAManifest manifest{};
485:     if (!fetchAndVerifyManifest_(manifest)) {
486:         // fetchAndVerifyManifest_ already sets _state, _lastOtaError, and
487:         // publishes a progress event on failure.
488:         if (!_silentCheck) {
489:             // Error state already set by fetchAndVerifyManifest_
490:         } else {
491:             // Silent check: suppress error modal, return to idle
492:             _state = OTAState::Idle;
493:             _lastOtaError = nullptr;
494:         }
495:         _silentCheck = false;
496:         return;
497:     }
498: 
499:     // --- Step 2: Channel lookup — direct, no risk-floor scanning ---
500:     // The deploy script (WO4) ensures each channel entry in the manifest
501:     // already contains the best available version for that risk floor.
502:     const OTAChannel* channel = findChannel(manifest, _channel);
503:     if (channel == nullptr) {
504:         ESP_LOGW(TAG, "Channel '%s' not found in manifest (channels=%d) — no update for this channel",
505:                  _channel, manifest.channelCount);
506:         // Fail-closed: if the manifest doesn't contain our channel, do not
507:         // attempt any update. This is not an error — it just means no release
508:         // has been published for this channel yet.
509:         if (!_silentCheck) {
510:             // Not an error condition — just no update available
511:         }
512:         _state = OTAState::Idle;
513:         _silentCheck = false;
514:         return;
515:     }
516: 
517:     ESP_LOGI(TAG, "Channel '%s' found — manifest version: %s, securityVersion: %u",
518:              _channel, channel->version, (unsigned)channel->securityVersion);
519: 
520:     // --- Step 3: SemVer comparison — only proceed if remote > local ---
521:     FirmwareVersion local = { VERSION_MAJOR, VERSION_MINOR, VERSION_PATCH,
522:                               static_cast<Channel>(VERSION_CHANNEL), VERSION_PRE_NUM };
523:     FirmwareVersion remote = parseVersionTag(channel->version);
524: 
525:     if (!(remote > local)) {
526:         // Check for implicit downgrade: channel changed since last check
527:         // e.g., switched from beta to stable — allow "downgrade" to the latest stable
528:         if (strcmp(_channel, _lastCheckedChannel) != 0 && _lastCheckedChannel[0] != '\0') {
529:             ESP_LOGI(TAG, "Channel changed ('%s' → '%s') — allowing implicit version change",
530:                      _lastCheckedChannel, _channel);
531:             strlcpy(_lastCheckedChannel, _channel, sizeof(_lastCheckedChannel));
532:             if (_configManager != nullptr) {
533:                 _configManager->saveModuleConfig(static_cast<IConfigurable*>(this));
534:             }
535:             // Fall through to download — channel switch is an implicit update
536:         } else {
537:             ESP_LOGI(TAG, "No update needed — local %s is current or newer than remote %s (channel='%s')",
538:                      BUILD_VERSION, channel->version, _channel);
539:             strlcpy(_lastCheckedChannel, _channel, sizeof(_lastCheckedChannel));
540:             _state = OTAState::Idle;
541:             _silentCheck = false;
542:             return;
543:         }
544:     } else {
545:         ESP_LOGI(TAG, "Update available: %s > %s (channel='%s') — proceeding",
546:                  channel->version, BUILD_VERSION, _channel);
547:     }
