549:     // Update lastCheckedChannel
550:     strlcpy(_lastCheckedChannel, _channel, sizeof(_lastCheckedChannel));
551: 
552:     // --- Step 4: Board asset lookup ---
553:     const OTAAsset* asset = findAssetForBoard(*channel, BOARD_ID);
554:     if (asset == nullptr) {
555:         ESP_LOGE(TAG, "No asset for board '%s' in channel '%s' (assets=%d)",
556:                  BOARD_ID, _channel, channel->assetCount);
557:         publishProgress(0.0f, "No firmware for this board", true, false);
558:         _state = OTAState::Error;
559:         _lastOtaError = "No firmware asset for this board in manifest";
560:         _silentCheck = false;
561:         return;
562:     }
563: 
564:     ESP_LOGI(TAG, "Asset resolved — board: '%s', firmware: %s, signature: %s, size: %u",
565:              asset->board, asset->firmwareUrl, asset->signatureUrl, (unsigned)asset->size);
566: 
567:     // Only now transition to Downloading — a download will actually happen
568:     _state = OTAState::Downloading;
569:     publishProgress(0.0f, "Update found — preparing download...", false, false);
570:     _silentCheck = false;
571: 
572:     // --- Step 5: Snapshot config manifest: Active → Previous before download ---
573:     _configManager->getManifest().snapshotActiveToPrevious();
574:     _configManager->getManifest().save();
575:     ESP_LOGI(TAG, "Config manifest: Active → Previous snapshot saved");
