577:     // --- Step 6: Initialize the verifier (if public key configured) ---
578:     MbedTLSSignatureVerifier verifier;
579:     bool verifierReady = false;
580: 
581:     if (cfg.otaPublicKey != nullptr) {
582:         _state = OTAState::Verifying;
583:         if (!verifier.begin(cfg.otaPublicKey)) {
584:             ESP_LOGE(TAG, "Failed to initialize MbedTLS verifier with public key");
585:             publishProgress(0.0f, "Verifier initialization failed", true, false);
586:             _state = OTAState::Error;
587:             _lastOtaError = "Verifier initialization failed";
588:             return;
589:         }
590:         verifierReady = true;
591:         ESP_LOGI(TAG, "Verifier initialized with public key");
592:         _state = OTAState::Downloading;
593:     }
594: 
595:     // --- Step 7: Create WiFiClientSecure on the heap ---
596:     std::unique_ptr<WiFiClientSecure> client(new (std::nothrow) WiFiClientSecure());
597:     if (!client) {
598:         ESP_LOGE(TAG, "Failed to allocate WiFiClientSecure on heap");
599:         publishProgress(0.0f, "Memory allocation failed", true, false);
600:         _state = OTAState::Error;
601:         _lastOtaError = "WiFiClientSecure heap allocation failed";
602:         return;
603:     }
604:     // Binary download uses setInsecure() — the firmware payload is independently
605:     // verified via MbedTLSSignatureVerifier (RSA-2048 signature). Transport
606:     // security is redundant. GitHub CDN redirects use different certs than the API
607:     // and root CAs may rotate over the device's operational lifetime.
608:     client->setInsecure();
609:     ESP_LOGI(TAG, "WiFiClientSecure allocated on heap");
