612:     OTADownloadEngine engine;
613:     if (verifierReady) {
614:         engine.setVerifier(&verifier);
615:     }
616: 
617:     // Set progress callback to forward to EventBus
618:     // Download progress maps to 2%-100% range (0%-2% covers manifest/sig phases)
619:     engine.setProgressCallback([](void* ctx, size_t bytesWritten, size_t totalSize) {
620:         auto* self = static_cast<OTAUpdateManager*>(ctx);
621:         float rawProgress = (totalSize > 0)
622:             ? static_cast<float>(bytesWritten) / static_cast<float>(totalSize)
623:             : 0.0f;
624:         float progress = 0.02f + (rawProgress * 0.98f); // 2% .. 100%
625:         self->publishProgress(progress, "Downloading firmware...", false, false);
626:         // Feed the Task Watchdog during firmware download — each progress
627:         // callback fires every ~4KB, keeping the WDT alive through multi-MB
628:         // transfers and TLS renegotiations.
629:         esp_task_wdt_reset();
630:     }, this);
631:     ESP_LOGI(TAG, "Download engine configured");
632: 
633:     // --- Step 9: Fetch signature file using manifest asset URL ---
634:     uint8_t sigBuf[512];
635:     size_t sigLen = 0;
636:     std::string token = cfg.otaToken ? cfg.otaToken : "";
637: 
638:     if (asset->signatureUrl[0] != '\0') {
639:         std::string sigUrlStr(asset->signatureUrl);
640:         sigLen = engine.fetchSignature(*client, sigUrlStr, token, sigBuf, sizeof(sigBuf));
641:         if (sigLen == 0 && cfg.otaPublicKey != nullptr) {
642:             ESP_LOGE(TAG, "SECURITY ABORT: Signature fetch returned 0 bytes — refusing update");
643:             publishProgress(0.0f, "Signature fetch failed — update rejected", true, false);
644:             _state = OTAState::Error;
645:             _lastOtaError = "Signature empty — update rejected (fail-closed)";
646:             return;
647:         } else if (sigLen > 0) {
648:             ESP_LOGI(TAG, "Fetched firmware signature: %u bytes", (unsigned)sigLen);
649:         }
650:     } else if (cfg.otaPublicKey != nullptr) {
651:         ESP_LOGE(TAG, "SECURITY ABORT: No signature URL in manifest but otaPublicKey is configured — refusing unsigned firmware");
652:         publishProgress(0.0f, "Missing signature URL — update rejected", true, false);
653:         _state = OTAState::Error;
654:         _lastOtaError = "No signature URL in manifest — update rejected (fail-closed)";
655:         return;
656:     }
657: 
658:     publishProgress(0.02f, "Downloading firmware...", false, false);
659: 
660:     // --- Step 10: Download and flash firmware using manifest asset URL ---
661:     // Set expected version for pre-flash binary validation safety gate.
662:     // channel->version contains the SemVer string (e.g. "v0.0.11-dev.14")
663:     // from the signed manifest. The engine strips the leading 'v' and
664:     // compares against the esp_app_desc_t.version field in the first chunk
665:     // of the downloaded binary before any flash writes occur.
666:     engine.setExpectedVersion(channel->version);
667: 
668:     std::string binUrlStr(asset->firmwareUrl);
669: 
670:     // Register with TWDT only for the download phase — the progress callback
671:     // feeds the watchdog every ~4KB. All prior phases (manifest, signature)
672:     // involve unpredictable blocking I/O and must NOT be under TWDT.
673:     esp_task_wdt_add(NULL);
674:     OTAError result = engine.downloadAndFlash(*client, binUrlStr, token, sigBuf, sigLen);
675:     esp_task_wdt_delete(NULL);
676: 
677:     if (result != OTAError::None) {
678:         _lastOtaError = engine.getLastErrorString();
679:         ESP_LOGE(TAG, "OTA download failed: %s", _lastOtaError);
680:         AUDIT("ota", "pipeline_failed", nullptr, _lastOtaError);
681:         publishProgress(0.0f, _lastOtaError, true, false);
682:         _state = OTAState::Error;
683:         return;
684:     }
685: 
686:     ESP_LOGI(TAG, "Firmware downloaded and verified successfully");
687: 
688:     // --- Step 11: Finalize ---
689:     _state = OTAState::Complete;
690:     publishProgress(1.0f, "Update complete — rebooting...", true, true);
691:     ESP_LOGI(TAG, "OTA update complete — rebooting in 2 seconds");
692:     AUDIT_SYNC("ota", "pipeline_complete", nullptr, "rebooting");
693: 
694:     // SAFETY: TWDT was deregistered above. This delay is safe only because
695:     // we are outside TWDT scope. Do not move TWDT deregistration below.
696:     delay(2000);  // Allow event propagation and display update
697: 
698:     if (_preRebootHook) {
699:         ESP_LOGI(TAG, "Executing pre-reboot hook before restart");
700:         _preRebootHook(_preRebootHookCtx);
701:     }
702: 
703:     ESP_LOGI(TAG, "OTA task stack high-water mark: %u bytes free",
704:              static_cast<unsigned>(uxTaskGetStackHighWaterMark(nullptr) * sizeof(StackType_t)));
705: 
706:     ESP.restart();
707: }
