166:   function setToggleState(checkbox, checked) {
167:     checkbox.checked = checked;
168:     const slider = checkbox.nextElementSibling;
169:     if (!slider) return;
170:     const dot = slider.querySelector('span');
171:     slider.style.background = checked ? 'var(--primary)' : 'var(--border)';
172:     if (dot) dot.style.left = checked ? '22px' : '3px';
173:   }
