178:   function infoRow(label, value, borderBottom) {
179:     const border = borderBottom !== false ? 'border-bottom:1px solid var(--border);' : '';
180:     return `<div style="display:flex; justify-content:space-between; padding:0.4rem 0; ${border} font-size:0.85rem;">
181:       <span style="color:var(--text-muted);">${label}</span>
182:       <strong>${value}</strong>
183:     </div>`;
184:   }
