186:   // -------------------------------------------------------------------------
187:   // Helper: Format firmware version with release notes hyperlink
188:   // -------------------------------------------------------------------------
189:   function formatVersionLink(ver, baseUrl) {
190:     if (!ver || ver === '?' || ver === 'unknown') {
191:       return ver === 'unknown' ? 'unknown' : 'v' + (ver || '?');
192:     }
193:     const tag = (ver.startsWith('v') || ver.startsWith('V')) ? ver : 'v' + ver;
194:     const template = baseUrl || 'https://github.com/matthewmcneill/esp32-app-foundation-releases/releases/tag/{version}';
195:     const url = template.includes('{version}')
196:       ? template.replace('{version}', encodeURIComponent(tag))
197:       : template.replace(/\/+$/, '') + '/' + encodeURIComponent(tag);
198:     return `<a href="${url}" target="_blank" rel="noopener noreferrer" style="color:var(--primary); text-decoration:underline;">${tag}</a>`;
199:   }
200: 
201:   // -------------------------------------------------------------------------
202:   // Load and render: Card 1 (Firmware) + Card 2 initial state (Settings)
203:   // Single merged call: /api/system + /api/ota status
204:   // -------------------------------------------------------------------------
205:   async function loadStatus() {
206:     const infoEl = document.getElementById('ota-firmware-info');
207: 
208:     try {
209:       // Both calls in parallel
210:       const [sys, ota] = await Promise.all([
211:         window.apiFetch('/api/system'),
212:         window.apiFetch('/api/ota', {
213:           method: 'POST',
214:           headers: { 'Content-Type': 'application/json' },
215:           body: JSON.stringify({ action: 'status' })
216:         })
217:       ]);
218: 
219:       // --- Card 1: Firmware ---
220:       let rows = '';
221:       rows += infoRow('Version',   formatVersionLink(ota.version || sys.firmware_version, ota.releaseNotesUrl || sys.release_notes_url));
222:       rows += infoRow('Partition', sys.partition || '?');
223:       rows += infoRow('Board',     ota.boardId   || '?');
224:       if (ota.lastError) {
225:         rows += infoRow('Last Error',
226:           '<span style="color:var(--error);">' + ota.lastError + '</span>', false);
227:       }
228:       infoEl.innerHTML = rows;
229: 
230:       // Card 2: Settings — restore saved state
231:       if (ota.channel) {
232:         document.getElementById('ota-channel').value = ota.channel;
233:       }
234:       const updatesEnabledCb = document.getElementById('ota-updates-enabled');
235:       if (updatesEnabledCb && ota.hasOwnProperty('updatesEnabled')) {
236:         setToggleState(updatesEnabledCb, !!ota.updatesEnabled);
237:       }
238:       const autoCheckCb = document.getElementById('ota-autocheck');
239:       if (autoCheckCb && ota.hasOwnProperty('autoCheck')) {
240:         setToggleState(autoCheckCb, !!ota.autoCheck);
241:       }
242:       if (ota.hasOwnProperty('checkHour')) {
243:         document.getElementById('ota-check-hour').value = ota.checkHour;
244:       }
245: 
246:       // --- Card 3: Low-memory advisory ---
247:       const warningEl = document.getElementById('ota-low-memory-warning');
248:       const detailEl  = document.getElementById('ota-low-memory-detail');
249:       if (warningEl && detailEl && ota.dram_free_bytes !== undefined && ota.ota_stack_bytes !== undefined) {
250:         const freeMem   = ota.dram_free_bytes;
251:         const required  = ota.ota_stack_bytes;
252:         if (freeMem < required) {
253:           const freeKB     = Math.round(freeMem / 1024);
254:           const requiredKB = Math.round(required / 1024);
255:           detailEl.textContent =
256:             `Free DRAM: ${freeKB} KB — Required: ${requiredKB} KB.` +
257:             ` Device has PSRAM fallback enabled but low DRAM may cause task delays.`;
258:           warningEl.style.display = 'block';
259:         } else {
260:           warningEl.style.display = 'none';
261:         }
262:       }
263: 
264:     } catch (error) {
265:       infoEl.innerHTML = '<p style="color:var(--error);">Error loading firmware info.</p>';
266:     }
267:   }
268: 
269:   // -------------------------------------------------------------------------
270:   // Card 3: Check for Updates
271:   // -------------------------------------------------------------------------
272:   let statusPollInterval = null;
273:   let checkInFlight = false; // true while a check/download task is running
274: 
275:   document.getElementById('btn-ota-check').addEventListener('click', async () => {
276:     const statusEl = document.getElementById('ota-check-status');
277:     const btn = document.getElementById('btn-ota-check');
278: 
279:     btn.disabled = true;
280:     btn.textContent = 'Checking...';
281:     statusEl.style.color = 'var(--primary)';
282:     statusEl.textContent = 'Querying GitHub for updates...';
283:     // Hide progress bar — it will only appear if a real download starts
284:     document.getElementById('ota-progress-wrapper').style.display = 'none';
285: 
286:     try {
287:       const response = await window.apiFetch('/api/ota', {
288:         method: 'POST',
289:         headers: { 'Content-Type': 'application/json' },
290:         body: JSON.stringify({ action: 'checkGithub' })
291:       });
292: 
293:       const msg = response.msg || 'Check complete';
294:       statusEl.style.color = 'var(--primary)';
295:       statusEl.textContent = msg;
296: 
297:       // Always start polling — we need to watch the background task
298:       // to distinguish "no update found" from "download in progress"
299:       checkInFlight = true;
300:       startStatusPolling();
301:     } catch (error) {
302:       statusEl.style.color = 'var(--error)';
303:       statusEl.textContent = 'Failed to check for updates.';
304:       checkInFlight = false;
305:     } finally {
306:       btn.disabled = false;
307:       btn.textContent = 'Check for Updates';
308:     }
309:   });
310: 
311:   function startStatusPolling() {
312:     if (statusPollInterval) clearInterval(statusPollInterval);
313:     statusPollInterval = setInterval(pollOtaStatus, 2000);
314:     pollOtaStatus();
315:   }
316: 
317:   function stopStatusPolling() {
318:     if (statusPollInterval) {
319:       clearInterval(statusPollInterval);
320:       statusPollInterval = null;
321:     }
322:   }
