311:   function startStatusPolling() {
312:     if (statusPollInterval) clearInterval(statusPollInterval);
313:     statusPollInterval = setInterval(pollOtaStatus, 2000);
314:     pollOtaStatus();
315:   }
316: 
317:   function stopStatusPolling() {
318:     if (statusPollInterval) {
319:       clearInterval(statusPollInterval);
320:       statusPollInterval = null;
321:     }
322:   }
