324:   async function pollOtaStatus() {
325:     try {
326:       const response = await window.apiFetch('/api/ota', {
327:         method: 'POST',
328:         headers: { 'Content-Type': 'application/json' },
329:         body: JSON.stringify({ action: 'status' })
330:       });
331: 
332:       const state    = response.state || 'unknown';
333:       const labelEl  = document.getElementById('ota-progress-label');
334:       const barEl    = document.getElementById('ota-progress-bar');
335:       const pctEl    = document.getElementById('ota-progress-pct');
336:       const statusEl = document.getElementById('ota-check-status');
337:       const wrapper  = document.getElementById('ota-progress-wrapper');
338: 
339:       // --- States that don't show the progress bar ---
340:       if (state === 'idle') {
341:         stopStatusPolling();
342:         wrapper.style.display = 'none';
343:         if (checkInFlight) {
344:           // Task ran and returned to idle without downloading — firmware is current
345:           statusEl.style.color = 'var(--success)';
346:           statusEl.textContent = '✓ Already up to date';
347:           checkInFlight = false;
348:         }
349:         return;
350:       }
351: 
352:       if (state === 'checking') {
353:         // Still querying GitHub — update status text only, no bar yet
354:         wrapper.style.display = 'none';
355:         statusEl.style.color = 'var(--primary)';
356:         statusEl.textContent = 'Checking GitHub...';
357:         return;
358:       }
359: 
360:       // --- States that show the progress bar ---
361:       wrapper.style.display = 'block';
362:       let pct = Math.round((response.progress || 0) * 100);
363:       let label = state, barColor = 'var(--primary)';
364: 
365:       switch (state) {
366:         case 'downloading':
367:           label = 'Downloading firmware...';
368:           statusEl.style.color = 'var(--primary)';
369:           statusEl.textContent = 'Update found — downloading...';
370:           break;
371:         case 'verifying':
372:           label = 'Verifying signature...';
373:           statusEl.style.color = 'var(--primary)';
374:           statusEl.textContent = 'Verifying signature...';
375:           break;
376:         case 'complete':
377:           pct = 100; label = 'Update complete — rebooting...';
378:           barColor = 'var(--success, #2e7d32)';
379:           stopStatusPolling();
380:           checkInFlight = false;
381:           statusEl.style.color = 'var(--success)';
382:           statusEl.textContent = 'Update complete! Device is rebooting.';
383:           window.showRebootOverlay('Applying firmware update…', 'The device will restart with the new firmware.');
384:           break;
385:         case 'error':
386:           pct = 100; label = 'Error: ' + (response.lastError || 'Unknown error');
387:           barColor = 'var(--error, #c62828)';
388:           stopStatusPolling();
389:           checkInFlight = false;
390:           wrapper.style.display = 'none';
391:           statusEl.style.color = 'var(--error)';
392:           statusEl.textContent = response.lastError || 'OTA update failed.';
393:           return;
394:       }
395: 
396:       labelEl.textContent    = label;
397:       barEl.style.width      = pct + '%';
398:       barEl.style.background = barColor;
399:       pctEl.textContent      = pct + '%';
400: 
401:     } catch (error) {
402:       document.getElementById('ota-progress-label').textContent = 'Connection lost...';
403:       stopStatusPolling();
404:       checkInFlight = false;
405:     }
406:   }
