525:   // Uses XMLHttpRequest directly (bypasses ApiQueue) for upload progress tracking.
526:   // Firmware is rejected server-side if ECDSA verification fails.
527:   // -------------------------------------------------------------------------
528:   document.getElementById('btn-ota-upload').addEventListener('click', () => {
529:     const binInput  = document.getElementById('ota-file-bin');
530:     const sigInput  = document.getElementById('ota-file-sig');
531:     const statusEl  = document.getElementById('ota-upload-status');
532:     const wrapper   = document.getElementById('ota-upload-progress-wrapper');
533:     const barEl     = document.getElementById('ota-upload-progress-bar');
534:     const pctEl     = document.getElementById('ota-upload-progress-pct');
535:     const labelEl   = document.getElementById('ota-upload-progress-label');
536:     const uploadBtn = document.getElementById('btn-ota-upload');
537: 
538:     if (!binInput.files[0] || !sigInput.files[0]) {
539:       statusEl.style.color = 'var(--error)';
540:       statusEl.textContent = 'Please select both a .bin and a .sig file.';
541:       return;
542:     }
543: 
544:     // Disable button during upload
545:     uploadBtn.disabled = true;
546:     uploadBtn.style.cursor = 'not-allowed';
547: 
548:     const formData = new FormData();
549:     formData.append('signature',  sigInput.files[0]);
550:     formData.append('firmware',   binInput.files[0]);
551: 
552:     // Show progress bar
553:     wrapper.style.display = 'block';
554:     barEl.style.width = '0%';
555:     barEl.style.background = 'var(--primary)';
556:     pctEl.textContent = '0%';
557:     labelEl.textContent = 'Uploading firmware...';
558:     statusEl.style.color = 'var(--primary)';
559:     statusEl.textContent = '';
560: 
561:     const xhr = new XMLHttpRequest();
562:     xhr.open('POST', '/api/ota/upload', true);
563:     xhr.timeout = 120000; // 120 second timeout
564: 
565:     // --- Upload progress ---
566:     xhr.upload.onprogress = function(e) {
567:       if (e.lengthComputable) {
568:         const pct = Math.round((e.loaded / e.total) * 100);
569:         barEl.style.width = pct + '%';
570:         pctEl.textContent = pct + '%';
571:         const kb = Math.round(e.loaded / 1024);
572:         const totalKb = Math.round(e.total / 1024);
573:         labelEl.textContent = 'Uploading... ' + kb + ' / ' + totalKb + ' KB';
574:       }
575:     };
576: 
577:     // --- Upload complete (sent) — now waiting for server verification ---
578:     xhr.upload.onload = function() {
579:       barEl.style.width = '100%';
