581:       labelEl.textContent = 'Verifying signature & writing to flash...';
582:       barEl.style.background = 'var(--warning, #f9a825)';
583:       statusEl.style.color = 'var(--text-muted)';
584:       statusEl.textContent = 'Please do not disconnect.';
