590:       try { result = JSON.parse(xhr.responseText); } catch(e) { result = {}; }
591: 
592:       if (xhr.status >= 200 && xhr.status < 300) {
593:         barEl.style.background = 'var(--success)';
594:         labelEl.textContent = 'Complete!';
595:         statusEl.style.color = 'var(--success)';
596:         statusEl.textContent = result.msg || 'Firmware verified and flashed — rebooting.';
597:         binInput.value = '';
